-- ============================================================
-- VueLibV4  ComponentMeta.PropertyConfigJson 属性面板配置（M3）
-- 幂等：仅当 PropertyConfigJson 为空时补齐，已配置（含手工/旧版）的组件不覆盖。
-- 规范：PCJ 必须是引用已注册组件的“真配置树”：
--   根 = DynElContainer(vertical)，子节点 modelname 为相对选中 cfg 的点路径
--   （如 options.comoptions.placeholder），由 RightPanel 的 DynDynamicCom 渲染，
--   v-model 经 _BaseLayout 的 _.get/_.set 直接回写画布 cfg，编辑即时生效。
-- 注意：JSON 内不使用单引号，整段以单引号包裹供 SQLite 执行。
-- ============================================================

-- ---------------- 表单控件 ----------------
UPDATE ComponentMeta SET PropertyConfigJson='{"component":"DynElContainer","modelname":"","options":{"comoptions":{"direction":"vertical"},"comlisteners":{},"labeloptions":{"label":"","required":false,"show":false},"itemoptions":{"style":{"gap":"0"},"class":""}},"validators":[],"childrenctrls":[{"component":"DynElInput","modelname":"options.comoptions.placeholder","options":{"comoptions":{},"labeloptions":{"label":"占位提示","show":true},"itemoptions":{}}},{"component":"DynElSwitch","modelname":"options.comoptions.clearable","options":{"comoptions":{},"labeloptions":{"label":"可清空","show":true},"itemoptions":{}}},{"component":"DynElSwitch","modelname":"options.comoptions.disabled","options":{"comoptions":{},"labeloptions":{"label":"禁用","show":true},"itemoptions":{}}},{"component":"DynElSwitch","modelname":"options.comoptions.readonly","options":{"comoptions":{},"labeloptions":{"label":"只读","show":true},"itemoptions":{}}},{"component":"DynElInputNumber","modelname":"options.comoptions.maxlength","options":{"comoptions":{"min":0},"labeloptions":{"label":"最大长度","show":true},"itemoptions":{}}},{"component":"DynElSwitch","modelname":"options.comoptions.showWordLimit","options":{"comoptions":{},"labeloptions":{"label":"字数统计","show":true},"itemoptions":{}}}],"slots":{},"extendinfo":{}}'
WHERE ComponentName='DynElInput' AND (PropertyConfigJson IS NULL OR trim(PropertyConfigJson)='');

